AND ( u.username LIKE CONCAT('%', #{searchKeyword}, '%') OR u.real_name LIKE CONCAT('%', #{searchKeyword}, '%') OR u.phone LIKE CONCAT('%', #{searchKeyword}, '%') OR u.email LIKE CONCAT('%', #{searchKeyword}, '%') OR r.role_name LIKE CONCAT('%', #{searchKeyword}, '%') )
